const fs = require('fs');
const puppeteer = require('puppeteer-core');
const BASE='https://dev.elmercadodeorigen.com';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const failures=[]; const checks={};
async function go(page,path,delay=650){const u=`${BASE}${path}${path.includes('?')?'&':'?'}device81=${Date.now()}`;const r=await page.goto(u,{waitUntil:'domcontentloaded',timeout:60000});await page.addStyleTag({content:'#cookie-law-info-bar,#cookie-law-info-again,#ht-ctc-chat{display:none!important}'}).catch(()=>{});await sleep(delay);if(!r||r.status()>=400)failures.push(`${path}: HTTP ${r?.status()||'none'}`);}
async function pos(page,path,selector){await go(page,path);const before=await page.evaluate(sel=>{const e=[...document.querySelectorAll(sel)].find(n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);return r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'&&+s.opacity>0});if(!e)return null;const r=e.getBoundingClientRect();return Math.round((r.top+scrollY)*10)/10},selector);if(before===null)return null;await page.evaluate(()=>scrollTo(0,170));await sleep(260);const after=await page.evaluate(sel=>{const e=[...document.querySelectorAll(sel)].find(n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);return r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'&&+s.opacity>0});if(!e)return null;const r=e.getBoundingClientRect();return Math.round((r.top+scrollY)*10)/10},selector);await page.evaluate(()=>scrollTo(0,0));return{top:before,after,delta:after===null?null:Math.round(Math.abs(after-before)*10)/10};}
async function group(page,label,surfaces,tol=2.5){const vals=[];for(const [path,sel] of surfaces){const m=await pos(page,path,sel);checks[`${label}:${path}`]=m;if(!m){failures.push(`${label} ${path}: surface missing (${sel})`);continue}vals.push([path,m.top]);if(m.delta===null||m.delta>2)failures.push(`${label} ${path}: moves on first scroll ${JSON.stringify(m)}`)}if(vals.length>1){const a=vals.map(v=>v[1]),spread=Math.round((Math.max(...a)-Math.min(...a))*10)/10;checks[`${label}:spread`]={spread,vals};if(spread>tol)failures.push(`${label}: starts differ ${spread}px ${JSON.stringify(vals)}`)}}
async function starts(page,width){await group(page,`paper-${width}`,[['/tienda/','main.site-main .emo-kicker'],['/quienes-somos/','.emo-about-intro .emo-kicker'],['/carrito/','.emo-cart-intro .emo-kicker'],['/finalizar-compra/','.emo-checkout-intro .emo-kicker']]);await group(page,`green-${width}`,[['/contacto/','.emo-contact-aside'],['/contacto-productores/','.emo-contact-aside'],['/productores/','.emo-producers-intro'],['/blog/','.emo-journal-hero__inner']]);}
async function filter(page,width){await page.setViewport({width,height:800,deviceScaleFactor:1,isMobile:true,hasTouch:true});await go(page,'/tienda/',800);const t=await page.$('#emo-premium-filter-toggle');if(!t){failures.push(`${width}px filter toggle missing`);return}await t.click();await sleep(600);const d=await page.evaluate(()=>{const sh=document.querySelector('#emo-premium-filter-shell'),c=sh?.querySelector('.emo-mobile-filter-content');const hs=[...(sh?.querySelectorAll('.emo-mobile-filter-content .widget > .widget-title,.emo-mobile-filter-content .widget > .sidebar-heading,.emo-mobile-filter-content .widget > .widget-heading,.emo-mobile-filter-content .widget > .wp-block-heading')||[])].slice(0,3).map(e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);return{w:r.width,h:r.height,radius:s.borderRadius,bg:s.backgroundColor,size:s.fontSize}});const pw=sh?.querySelector('.widget_price_filter'),amount=pw?.querySelector('.price_slider_amount'),next=pw?.nextElementSibling,nh=next?.querySelector(':scope > .widget-title,:scope > .sidebar-heading,:scope > .widget-heading,:scope > .wp-block-heading');const ar=amount?.getBoundingClientRect(),nr=nh?.getBoundingClientRect(),pwr=pw?.getBoundingClientRect(),nwr=next?.getBoundingClientRect();const tr=sh?.querySelector('.widget_price_filter .price_slider.ui-slider,.widget_price_filter .ui-slider-horizontal')?.getBoundingClientRect(),hrs=[...(sh?.querySelectorAll('.widget_price_filter .ui-slider-handle')||[])].slice(0,2).map(e=>e.getBoundingClientRect());const slider=tr&&hrs.length===2?{y:hrs.map(r=>Math.abs((r.top+r.height/2)-(tr.top+tr.height/2))),x:[Math.abs((hrs[0].left+hrs[0].width/2)-tr.left),Math.abs((hrs[1].left+hrs[1].width/2)-tr.right)]}:null;return{open:!!sh&&!sh.hidden,overflow:c?c.scrollWidth-c.clientWidth:null,heads:hs,sectionGap:ar&&nr?nr.top-ar.bottom:null,widgetGap:pwr&&nwr?nwr.top-pwr.bottom:null,slider}});checks[`filter-${width}`]=d;if(!d.open)failures.push(`${width}px filter closed`);if(d.overflow>2)failures.push(`${width}px filter overflow ${d.overflow}`);if(d.heads.length<3)failures.push(`${width}px filter headings missing`);else{const h=d.heads;if(Math.max(...h.map(x=>x.h))-Math.min(...h.map(x=>x.h))>1||Math.max(...h.map(x=>x.w))-Math.min(...h.map(x=>x.w))>1||new Set(h.map(x=>x.radius)).size!==1||new Set(h.map(x=>x.bg)).size!==1||new Set(h.map(x=>x.size)).size!==1)failures.push(`${width}px headings inconsistent ${JSON.stringify(h)}`)}if(d.sectionGap===null||d.sectionGap<18)failures.push(`${width}px section gap ${d.sectionGap}`);if(d.widgetGap===null||d.widgetGap<18)failures.push(`${width}px widget gap ${d.widgetGap}`);if(!d.slider)failures.push(`${width}px slider missing`);else if(Math.max(...d.slider.y)>1.5||Math.max(...d.slider.x)>2.5)failures.push(`${width}px slider misaligned ${JSON.stringify(d.slider)}`);await page.screenshot({path:`qa/filter-real-${width}.png`,fullPage:false});}
(async()=>{fs.mkdirSync('qa',{recursive:true});const products=await fetch(`${BASE}/wp-json/wc/store/v1/products?per_page=100`).then(r=>r.json()),p=products.find(x=>x.is_purchasable&&x.is_in_stock&&x.type==='simple');if(!p)throw new Error('No simple product');const b=await puppeteer.launch({executablePath:'/usr/bin/google-chrome',headless:'new',protocolTimeout:120000,args:['--no-sandbox','--disable-dev-shm-usage']});const page=await b.newPage();page.setDefaultNavigationTimeout(60000);await page.setUserAgent('Mozilla/5.0 (Linux; Android 14; SM-S918B) AppleWebKit/537.36 SamsungBrowser/28.0 Chrome/130.0 Mobile Safari/537.36');try{await page.setViewport({width:360,height:800,deviceScaleFactor:1,isMobile:true,hasTouch:true});await go(page,`/contacto/?add-to-cart=${p.id}`,850);await starts(page,360);for(const w of [360,375,390])await filter(page,w);await page.setViewport({width:390,height:844,deviceScaleFactor:1,isMobile:true,hasTouch:true});await starts(page,390);await page.setViewport({width:1440,height:1000,deviceScaleFactor:1});await starts(page,1440)}finally{await b.close()}fs.writeFileSync('qa/real-device-layout-check-01081.json',JSON.stringify({failures,checks},null,2));if(failures.length){console.error(failures.join('\n'));process.exitCode=2}else console.log(`REAL_DEVICE_LAYOUT_01081_OK ${JSON.stringify(checks)}`)})();
